                <pre style="font-size:12px;background:rgba(0,0,0,.15);border-radius:10px;padding:12px;margin-top:10px;overflow-x:auto;white-space:pre-wrap;line-height:1.5">-- ═══════════════════════════════════════════════════
-- ADERVIS — Схема базы данных v4.2
-- Выполнить один раз в Supabase SQL Editor
-- ═══════════════════════════════════════════════════

-- 1. Профили пользователей (подписка + принадлежность к агентству)
create table if not exists profiles (
  id uuid references auth.users on delete cascade primary key,
  email text,
  agency_id text,                   -- UUID агентства (= id владельца)
  subscription_status text default 'trial',
  subscription_plan text default 'pro',
  subscription_expires_at timestamptz default (now() + interval '7 days'),
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
alter table profiles enable row level security;
create policy "profiles: read own" on profiles for select using (auth.uid() = id);
create policy "profiles: insert own" on profiles for insert with check (auth.uid() = id);
create policy "profiles: update own" on profiles for update using (auth.uid() = id);

-- 2. Состояние агентства (общий workspace команды)
-- id = agency_id из profiles (= UUID владельца агентства)
create table if not exists agency_state (
  id text primary key,
  state_json jsonb,
  updated_at timestamptz default now()
);
alter table agency_state enable row level security;
-- Пользователь видит только данные своего агентства
create policy "state: read agency" on agency_state for select
  using (id = (select agency_id from profiles where profiles.id = auth.uid()));
create policy "state: insert agency" on agency_state for insert
  with check (id = (select agency_id from profiles where profiles.id = auth.uid()));
create policy "state: update agency" on agency_state for update
  using (id = (select agency_id from profiles where profiles.id = auth.uid()));

-- 3. Migrating: если таблицы уже существуют — добавить agency_id
alter table profiles add column if not exists agency_id text;
-- Заполнить agency_id = id для существующих пользователей
update profiles set agency_id = id::text where agency_id is null;

-- 4. Realtime: Database → Replication → agency_state → Insert+Update

-- 5. RPC: атомарное обновление telegramChatIds (избегаем race condition в команде)
create or replace function update_telegram_recipients(
  p_agency_id uuid,
  p_recipients jsonb
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_agency_id text;
begin
  select agency_id into v_user_agency_id from profiles where id = auth.uid();
  if v_user_agency_id is distinct from p_agency_id::text then
    raise exception 'Unauthorized';
  end if;
  update agency_state
    set state_json = jsonb_set(coalesce(state_json, '{}'), '{telegramChatIds}', p_recipients, true),
        updated_at = now()
    where id = p_agency_id;
  if not found then
    insert into agency_state (id, state_json, updated_at)
    values (p_agency_id, jsonb_build_object('telegramChatIds', p_recipients), now())
    on conflict (id) do update
      set state_json = jsonb_set(coalesce(agency_state.state_json, '{}'), '{telegramChatIds}', p_recipients, true),
          updated_at = now();
  end if;
end;
$$;
grant execute on function update_telegram_recipients(uuid, jsonb) to authenticated;</pre>
